const AL='123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
function enc(buf){
  let n=0n; for(const b of buf) n=n*256n+BigInt(b);
  let s=''; if(n===0n) s='';
  while(n>0n){ s=AL[Number(n%58n)]+s; n/=58n; }
  let pad=0; for(const b of buf){ if(b===0) pad++; else break; }
  return AL[0].repeat(pad)+(s===''?'':s);
}
// argv: hex bytes
const hex=process.argv[2];
const buf=Buffer.from(hex,'hex');
process.stdout.write(enc(buf));
EOF
node /tmp/p/b58.js 27 && echo "" && node /tmp/p/b58.js 5c && echo "" && node /tmp/p/b58.js 2722 && echo "" && node /tmp/p/b58.js 5c27 && echo ""

cat > /tmp/p/model.js <<'EOF'
// Python bytes repr model
function pyrepr(buf){
  const hasS=buf.includes(0x27), hasD=buf.includes(0x22);
  const q = (hasS && !hasD) ? '"' : "'";
  let s="b"+q;
  for(const b of buf){
    if(b===0x5c) s+="\\\\";
    else if(b===0x09) s+="\\t";
    else if(b===0x0a) s+="\\n";
    else if(b===0x0d) s+="\\r";
    else if(String.fromCharCode(b)===q) s+="\\"+q;
    else if(b>=0x20 && b<0x7f) s+=String.fromCharCode(b);
    else s+="\\x"+b.toString(16).padStart(2,'0');
  }
  return s+q;
}
module.exports={pyrepr};
if(require.main===module){
  process.stdout.write(pyrepr(Buffer.from(process.argv[2],'hex')));
}
EOF
E=/workspace/dataset/test20_executable
